function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function catOf(line){
  var b=line.match(/^\[([^\]]*)\]/);
  if(b){ var t=b[1];
    if(/新增/.test(t)) return 'Added';
    if(/修复/.test(t)) return 'Fixed';
    if(/废弃/.test(t)) return 'Deprecated';
    if(/移除|删除/.test(t)) return 'Removed';
    if(/安全/.test(t)) return 'Security';
    return 'Changed';
  }
  if(/新增|特性/.test(line)) return 'Added';
  if(/修复|缺陷/.test(line)) return 'Fixed';
  if(/废弃/.test(line)) return 'Deprecated';
  if(/移除|删除/.test(line)) return 'Removed';
  if(/安全|security/i.test(line)) return 'Security';
  return 'Changed';
}
function catLabel(c){ return {Added:'新增（Added）',Changed:'变更（Changed）',Fixed:'修复（Fixed）',Deprecated:'废弃（Deprecated）',Removed:'移除（Removed）',Security:'安全（Security）'}[c]; }
function buildReleaseNotes(o){
  o=o||{};
  var version=String(o.version||'1.0.0').trim()||'1.0.0';
  var date=String(o.date||'').trim();
  var lines0=splitLines(o.changes);
  var groups={Added:[],Changed:[],Fixed:[],Deprecated:[],Removed:[],Security:[]};
  var order=['Added','Changed','Fixed','Deprecated','Removed','Security'];
  lines0.forEach(function(l){ groups[catOf(l)].push(l); });
  var total=lines0.length;
  var lines=[];
  lines.push('# 发布说明 v'+version+(date?('（'+date+'）'):''));
  lines.push('');
  lines.push('> 本次发布共 '+total+' 项变更。');
  lines.push('');
  order.forEach(function(c){
    if(!groups[c].length) return;
    lines.push('## '+catLabel(c));
    groups[c].forEach(function(l){ lines.push('- '+l.replace(/^\[[^\]]*\]\s*/,'')); });
    lines.push('');
  });
  var counts={}; order.forEach(function(c){ counts[c]=groups[c].length; });
  return {version:version, total:total, counts:counts, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, catOf:catOf, buildReleaseNotes:buildReleaseNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReleaseNotesForgePure = EXPORTS; }
